package com.nextspace.app;

import android.app.*;
import android.appwidget.AppWidgetManager;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.Color;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import com.google.gson.*;
import java.util.*;

/** Native settings form. Choice catalog/defaults and all result selection come from shared core. */
public class NativeWidgetConfigurationActivity extends Activity {
    private int widgetId;private JsonObject config,catalog;private LinearLayout body;private EditText title,query;private final Map<String,Spinner> spinners=new HashMap<>();private final Map<String,List<String>> values=new HashMap<>();private final Map<String,CheckBox> checks=new HashMap<>();private SeekBar transparency;private TextView error;private String account;private boolean dark;
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);setResult(RESULT_CANCELED);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(!NativeWidgetProvider.owns(this,widgetId)){finish();return;}account=NativeWidgetStore.accountKey(this);dark=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;load(true);}
    private void load(boolean project){
        try{if(account.isEmpty())throw new Exception("Open NextGlance and connect your account before adding a widget.");NativeWidgetStore store=new NativeWidgetStore(this);catalog=NativeWidgetPolicy.object(store.state(account),"catalog");config=store.config(widgetId);boolean existing=NativeWidgetPolicy.validConfig(config)&&account.equals(NativeWidgetPolicy.text(config,"accountKey",""));if(!existing)config=NativeWidgetPolicy.object(NativeWidgetPolicy.object(catalog,"defaults"),"calendar").deepCopy();
            if(!NativeWidgetPolicy.validConfig(config)){if(project){screen();label("Preparing saved widget choices\u2026");NativeWidgetProjector.schedule(this,()->{if(!isFinishing())load(false);});return;}throw new Exception("Open NextGlance once to prepare saved widget sources, then add the widget again.");}
            if(!existing){screen();TextView heading=label("Choose a widget page");heading.setTextSize(23);label("Each widget keeps its own sources, filters and appearance.");for(String page:new String[]{"overview","calendar","timeline","board","list"}){Button button=button(page.substring(0,1).toUpperCase()+page.substring(1));button.setOnClickListener(v->{config=NativeWidgetPolicy.object(NativeWidgetPolicy.object(catalog,"defaults"),page).deepCopy();config.addProperty("widgetId",widgetId);build();});}Button cancel=button("Cancel");cancel.setOnClickListener(v->finish());return;}config.addProperty("widgetId",widgetId);build();
        }catch(Exception failure){screen();label(failure.getMessage());Button open=button("Open NextGlance");open.setOnClickListener(v->{startActivity(new Intent(this,MainActivity.class));finish();});Button close=button("Cancel");close.setOnClickListener(v->finish());}
    }
    private void screen(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(18),dp(18),dp(24));body.setBackgroundColor(Color.parseColor(dark?"#1d2532":"#ffffff"));scroll.addView(body);setContentView(scroll);spinners.clear();values.clear();checks.clear();}
    private TextView label(String value){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.parseColor(dark?"#eff4fb":"#243044"));t.setTextSize(14);t.setPadding(0,dp(12),0,dp(5));body.addView(t);return t;}
    private EditText edit(String name,String value,int max){label(name);EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);e.setTextColor(Color.parseColor(dark?"#eff4fb":"#243044"));e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(max)});e.setMinHeight(dp(48));body.addView(e);return e;}
    private Button button(String text){Button b=new Button(this);b.setText(text);b.setAllCaps(false);body.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));return b;}
    private Spinner choose(String key,String title,List<String> ids,List<String> labels,String selected){label(title);Spinner spinner=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(Math.max(0,ids.indexOf(selected)));body.addView(spinner,new LinearLayout.LayoutParams(-1,dp(48)));spinners.put(key,spinner);values.put(key,ids);return spinner;}
    private Spinner choose(String key,String title,String[] ids,String[] labels){return choose(key,title,List.of(ids),List.of(labels),NativeWidgetPolicy.text(config,key,ids[0]));}
    private String selected(String key){Spinner s=spinners.get(key);List<String> list=values.get(key);int i=s==null?-1:s.getSelectedItemPosition();return list==null||i<0||i>=list.size()?"":list.get(i);}
    private CheckBox check(String key,String text,boolean value){CheckBox c=new CheckBox(this);c.setText(text);c.setChecked(value);c.setTextColor(Color.parseColor(dark?"#eff4fb":"#243044"));c.setMinHeight(dp(44));body.addView(c);checks.put(key,c);return c;}
    private boolean contains(JsonArray list,String id){for(JsonElement e:list)if(e.isJsonPrimitive()&&id.equals(e.getAsString()))return true;return false;}
    private void multiple(String key,String label,String catalogKey,String valueField){Button b=button(label);Runnable update=()->b.setText(label+" ("+NativeWidgetPolicy.array(config,key).size()+")");update.run();b.setOnClickListener(v->{List<String> ids=new ArrayList<>(),labels=new ArrayList<>();String scope=selected("scopeId");for(JsonElement element:NativeWidgetPolicy.array(catalog,catalogKey)){JsonObject o=element.getAsJsonObject();if("sources".equals(catalogKey)&&!"all".equals(scope)&&!contains(NativeWidgetPolicy.array(o,"scopeIds"),scope))continue;if("statuses".equals(catalogKey)&&!scope.equals(NativeWidgetPolicy.text(o,"scopeId","all")))continue;ids.add(NativeWidgetPolicy.text(o,valueField,""));labels.add(NativeWidgetPolicy.text(o,"title",ids.get(ids.size()-1)));}boolean[] state=new boolean[ids.size()];for(int i=0;i<ids.size();i++)state[i]=contains(NativeWidgetPolicy.array(config,key),ids.get(i));new AlertDialog.Builder(this).setTitle(label).setMultiChoiceItems(labels.toArray(new String[0]),state,(d,which,on)->state[which]=on).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,which)->{JsonArray out=new JsonArray();for(int i=0;i<ids.size();i++)if(state[i])out.add(ids.get(i));config.add(key,out);update.run();}).show();});}
    private void build(){
        screen();TextView heading=label("Widget settings");heading.setTextSize(23);heading.setTypeface(null,android.graphics.Typeface.BOLD);label("Only this widget changes.");JsonObject savedSnapshot=new NativeWidgetStore(this).snapshot(widgetId);if(!savedSnapshot.isEmpty())label(NativeWidgetProvider.fullFreshness(savedSnapshot));title=edit("Name",NativeWidgetPolicy.text(config,"title","NextGlance"),80);
        choose("page","Page",new String[]{"overview","calendar","timeline","board","list"},new String[]{"Overview","Calendar","Timeline","Board","List"});
        List<String> scopeIds=new ArrayList<>(),scopeLabels=new ArrayList<>();for(JsonElement value:NativeWidgetPolicy.array(catalog,"spaces")){JsonObject scope=value.getAsJsonObject();scopeIds.add(NativeWidgetPolicy.text(scope,"id",""));scopeLabels.add(NativeWidgetPolicy.text(scope,"title",""));}if(!scopeIds.contains("all")){scopeIds.add(0,"all");scopeLabels.add(0,"My overview");}String currentScope=NativeWidgetPolicy.text(config,"scopeId","all");if(!scopeIds.contains(currentScope)){scopeIds.add(currentScope);scopeLabels.add("Unavailable Space");}choose("scopeId","Space",scopeIds,scopeLabels,currentScope);
        label("Include");JsonArray kinds=NativeWidgetPolicy.array(config,"kinds");check("event","Calendar events",contains(kinds,"event"));check("task","Tasks",contains(kinds,"task"));check("card","Deck cards",contains(kinds,"card"));
        label("Board displays Tasks and Deck cards. Select at least one supported item type.");spinners.get("page").setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View view,int position,long id){CheckBox event=checks.get("event");boolean board="board".equals(selected("page"));event.setEnabled(!board);if(board)event.setChecked(false);calendarChoices();}});
        choose("sourceMode","Sources",new String[]{"all","selected"},new String[]{"All eligible sources in this Space","Only selected sources"});multiple("collectionIds","Choose sources","sources","id");multiple("statusIds","Unified statuses (none means all)","statuses","id");multiple("projectIds","Projects (none means all)","projects","id");multiple("tagNames","Tags (none means all)","tags","title");
        choose("assignment","Assignment",new String[]{"all","me"},new String[]{"Everyone","Me"});check("includeUnassigned","Include unassigned",NativeWidgetPolicy.flag(config,"includeUnassigned",true));check("showCompleted","Show completed tasks",NativeWidgetPolicy.flag(config,"showCompleted",false));check("groupLinkedTasks","Group linked tasks with Deck cards",NativeWidgetPolicy.flag(config,"groupLinkedTasks",true));
        query=edit("Search text",NativeWidgetPolicy.text(config,"query",""),2000);
        choose("dateRange","Dates",new String[]{"all","today","week","month","overdue"},new String[]{"All dates","Today","Next 7 days","Next 31 days","Overdue"});choose("groupBy","Group by",new String[]{"planner","date","source","project","status","none"},new String[]{"App hierarchy","Date","Source","Project","Unified status","None"});choose("sort","Sort",new String[]{"date","title"},new String[]{"Date","Title"});choose("calendarLayout","Calendar layout",new String[]{"agenda","day","week","month"},new String[]{"Agenda","Today","Week","Month"});calendarChoices();choose("density","Density",new String[]{"compact","comfortable"},new String[]{"Compact","Comfortable"});choose("theme","Theme",new String[]{"system","light","dark"},new String[]{"System","Light","Dark"});
        TextView alpha=label("Background transparency: "+NativeWidgetPolicy.number(config,"transparency",32)+"%");transparency=new SeekBar(this);transparency.setMax(50);transparency.setProgress(NativeWidgetPolicy.number(config,"transparency",32));transparency.setContentDescription("Background transparency");body.addView(transparency,new LinearLayout.LayoutParams(-1,dp(44)));transparency.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){alpha.setText("Background transparency: "+n+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
        label("Creation destinations");for(String kind:new String[]{"event","task","card"})destination(kind);
        error=label("");error.setTextColor(Color.parseColor(dark?"#ffb0a9":"#a32824"));Button save=button("Save widget");save.setOnClickListener(v->save());Button cancel=button("Cancel");cancel.setOnClickListener(v->finish());
    }
    private void calendarChoices(){
        Spinner spinner=spinners.get("calendarLayout");if(spinner==null)return;
        String current=selected("calendarLayout");if(current.isEmpty())current=NativeWidgetPolicy.text(config,"calendarLayout","week");
        // An older Overview agenda/month value displays Week but remains saved until the user chooses Today.
        var choices=NativeWidgetPresentation.calendarChoices(selected("page"),current);List<String> ids=choices.ids(),labels=choices.labels();
        ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);values.put("calendarLayout",ids);spinner.setSelection(Math.max(0,ids.indexOf(current)));
    }
    private void destination(String kind){List<String> ids=new ArrayList<>(List.of("")),labels=new ArrayList<>(List.of("Choose when creating"));for(JsonElement e:NativeWidgetPolicy.array(catalog,"sources")){JsonObject s=e.getAsJsonObject();if(!kind.equals(NativeWidgetPolicy.text(s,"kind",""))||NativeWidgetPolicy.flag(s,"readonly",false))continue;String id=NativeWidgetPolicy.text(s,"id","");if("card".equals(kind)){for(JsonElement st:NativeWidgetPolicy.array(s,"stacks")){JsonObject stack=st.getAsJsonObject();ids.add(id+"\n"+NativeWidgetPolicy.text(stack,"id",""));labels.add(NativeWidgetPolicy.text(s,"title","")+" \u00b7 "+NativeWidgetPolicy.text(stack,"title",""));}}else{ids.add(id);labels.add(NativeWidgetPolicy.text(s,"title",""));}}JsonObject saved=NativeWidgetPolicy.object(NativeWidgetPolicy.object(config,"creationDefaults"),kind);String selected=NativeWidgetPolicy.text(saved,"collectionId","");if("card".equals(kind)&&!selected.isEmpty())selected+="\n"+NativeWidgetPolicy.text(saved,"stackId","");choose("create-"+kind,kind.equals("event")?"Calendar":kind.equals("task")?"Task list":"Deck board / stack",ids,labels,selected);}
    private void save(){try{
        if(!NativeWidgetProvider.owns(this,widgetId)||!account.equals(NativeWidgetStore.accountKey(this)))throw new Exception("The widget or account changed. Please reopen setup.");String name=title.getText().toString().trim();if(name.isEmpty())throw new Exception("Enter a widget name.");JsonObject out=config.deepCopy();out.addProperty("title",name);out.addProperty("query",query.getText().toString());for(String key:spinners.keySet())if(!key.startsWith("create-"))out.addProperty(key,selected(key));JsonArray kinds=new JsonArray();for(String kind:new String[]{"event","task","card"})if(checks.get(kind).isChecked())kinds.add(kind);if(kinds.isEmpty())throw new Exception("Choose at least one supported item type.");out.add("kinds",kinds);for(String key:new String[]{"includeUnassigned","showCompleted","groupLinkedTasks"})out.addProperty(key,checks.get(key).isChecked());out.addProperty("transparency",transparency.getProgress());JsonObject destinations=new JsonObject();for(String kind:new String[]{"event","task","card"}){String value=selected("create-"+kind);if(!value.isEmpty()){String[] parts=value.split("\n",2);JsonObject target=new JsonObject();target.addProperty("collectionId",parts[0]);if(parts.length==2)target.addProperty("stackId",parts[1]);destinations.add(kind,target);}}out.add("creationDefaults",destinations);new NativeWidgetStore(this).save(widgetId,out);NativeWidgetProvider.update(this,widgetId);NativeWidgetProjector.schedule(this);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();
    }catch(Exception failure){error.setText(failure.getMessage());}}
}
